  `domicilio_real_proyecto` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fecha_alta` date DEFAULT NULL,
  `fecha_creacion` date DEFAULT NULL,
  `licencia_comercial` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nombre_del_proponente` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
