  `razon_social` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `situacion_predio` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `superficie_cubierta` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `superficie_descubierta` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tecnologia` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tipo_de_contrato` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vencimiento_licencia_comercial` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_id` bigint DEFAULT NULL,
  `rrpp` varbinary(255) DEFAULT NULL,
  `vigente` bit(1) DEFAULT NULL,
  `descripcion` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `FK20t85d9gkoe3kwc9f5q2c6b05` (`user_id`),
  CONSTRAINT `FK20t85d9gkoe3kwc9f5q2c6b05` FOREIGN KEY (`user_id`) REFERENCES `usuarios` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
